import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"RNG Standardization","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/rng.md","filePath":"gameplay/rng.md","lastUpdated":1788364293000}'),o={name:"gameplay/rng.md"};function l(s,e,n,d,h,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="rng-standardization" tabindex="-1">RNG Standardization <a class="header-anchor" href="#rng-standardization" aria-label="Permalink to &quot;RNG Standardization&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>For a fair and competitive nature, MCSR Ranked standardizes some RNG (Random Number Generation) through the <strong>RNG Seed</strong>. As a result, all players in the match will experience the same loot rates in the same order.</p><p>The RNG Seed is same as Overworld seed by default. In a private room, you can use a different RNG Seed.</p><p>This document will describe what is standardized based on RNG Seed.</p><h2 id="piglin-barters" tabindex="-1">Piglin Barters <a class="header-anchor" href="#piglin-barters" aria-label="Permalink to &quot;Piglin Barters&quot;">​</a></h2><ul><li>Barter chances for Obsidian are increased by ~35%</li><li>At least 6 Obsidian is guaranteed every 72 barters (8 Gold Blocks)</li><li>Exactly 3 Ender Pearl trades are guaranteed every 72 barters (8 Gold Blocks)</li><li>All players in the match have the same trades in the same order</li></ul><h2 id="mob-drop-loot" tabindex="-1">Mob Drop Loot <a class="header-anchor" href="#mob-drop-loot" aria-label="Permalink to &quot;Mob Drop Loot&quot;">​</a></h2><h3 id="all-item-drop-rates-from-mobs-are-standardized-some-important-examples-are" tabindex="-1">All item drop rates from mobs are standardized, some important examples are: <a class="header-anchor" href="#all-item-drop-rates-from-mobs-are-standardized-some-important-examples-are" aria-label="Permalink to &quot;All item drop rates from mobs are standardized, some important examples are:&quot;">​</a></h3><ul><li>Food drops from animals and Hoglins</li><li>Blaze Rods from Blazes</li><li>Ender Pearls from Endermen</li></ul><h4 id="some-item-drops-are-forced" tabindex="-1">Some item drops are forced: <a class="header-anchor" href="#some-item-drops-are-forced" aria-label="Permalink to &quot;Some item drops are forced:&quot;">​</a></h4><ul><li>Iron Golems always drop 4 Iron (never 3 or 5)</li></ul><h2 id="block-drop-loot" tabindex="-1">Block Drop Loot <a class="header-anchor" href="#block-drop-loot" aria-label="Permalink to &quot;Block Drop Loot&quot;">​</a></h2><h3 id="all-item-drop-rates-from-blocks-are-standardized-some-important-examples-are" tabindex="-1">All item drop rates from blocks are standardized, some important examples are: <a class="header-anchor" href="#all-item-drop-rates-from-blocks-are-standardized-some-important-examples-are" aria-label="Permalink to &quot;All item drop rates from blocks are standardized, some important examples are:&quot;">​</a></h3><ul><li>Sticks from Dead Bushes</li><li>Apples from Leaves</li><li>Flint from Gravel</li><li>Gilded Blackstone from Gilded Blackstone</li><li>Glowstone Dust from Glowstone</li></ul><h2 id="item-usage" tabindex="-1">Item Usage <a class="header-anchor" href="#item-usage" aria-label="Permalink to &quot;Item Usage&quot;">​</a></h2><ul><li>Hunger effect rates from Rotten Flesh is standardized</li><li>Effects from Suspicious Stew are standardized <ul><li>Also, Suspicious Stew can never give Poison</li></ul></li><li>Wool rates from shearing sheep are standardized</li><li>Endermite spawn rates from Ender Pearl throws are standardized per dimension</li><li>Eye of Ender throw break rates are standardized <ul><li>Also, the 2nd eye throw will never break</li></ul></li></ul><h2 id="mob-behavior" tabindex="-1">Mob Behavior <a class="header-anchor" href="#mob-behavior" aria-label="Permalink to &quot;Mob Behavior&quot;">​</a></h2><ul><li>Villager trade offers are standardized</li><li>Drowned never spawn with a held Trident</li><li>Elder Guardians never afflict the player with Mining Fatigue</li><li>Monsters and Bats do not spawn in Desert Temples</li><li>Monsters do not spawn in Bastion Remnants except built-in entities</li><li>Zombified Piglins avoid pathfinding into Bastion Remnants</li><li>Magma Cube splitting amount is standardized</li><li>Ghasts do not spawn within 5 chunks of the player</li></ul><h2 id="mob-spawners" tabindex="-1">Mob Spawners <a class="header-anchor" href="#mob-spawners" aria-label="Permalink to &quot;Mob Spawners&quot;">​</a></h2><ul><li>Magma Cube spawning positions and sizes are standardized</li><li>Blaze spawning timings are standardized</li><li>Blaze spawning positions in spawners are standardized</li></ul><details class="details custom-block"><summary>Details about Spawner standardization logic</summary><p>The mod tries to attempt up to 4 spots in the spawner. These 4 spots are the same for both runners no matter which spawner. If any fire, block, entity or yourself is blocking the spot, you will NOT get that blaze. The time for these 4 spots to be chosen is the same, and thus this is why the blaze x,y,z are exactly the same as well. The 4 spots the mod tries to spawn are vanilla style, so it will have a large chance closer to the center of spawner.</p></details><ul><li>Zombie Spawners are replaced with either a Skeleton Spawner or a Spider Spawner</li></ul><h2 id="player-portal-behaviors" tabindex="-1">Player &amp; Portal Behaviors <a class="header-anchor" href="#player-portal-behaviors" aria-label="Permalink to &quot;Player &amp; Portal Behaviors&quot;">​</a></h2><ul><li>Player spawn coordinates are standardized</li><li>Initial Nether entry location is standardized by spawn coordinates. The Y level behaviour is standardized to 64.</li></ul><details class="details custom-block"><summary>Details</summary><p>Every portal is treated like you are building on Y64 in the overworld, however this does not guarantee Y64 in the Nether. If the Nether is buried from Y64-Y31, then your portal will be Y30. Regardless, the portal is standardized for X,Y,Z.</p></details><ul><li>First blind portal* will always spawn on the surface if built at Nether Y level 48 or above, so you rarely get caved.</li><li>The amount of already filled in End Portal Frames per End Portal is the same between all Strongholds.</li></ul><p>*First portal from Nether for travel to Stronghold.</p><h2 id="ender-dragon" tabindex="-1">Ender Dragon <a class="header-anchor" href="#ender-dragon" aria-label="Permalink to &quot;Ender Dragon&quot;">​</a></h2><ul><li>The sequence of target block height offsets is standardized within each phase <ul><li>The target block height offset for zero cycles is 0-15 blocks, as opposed to the 0-20 in vanilla</li></ul></li><li>Direction changes are standardized within each phase</li><li>Strafe rolls are standardized</li><li>Perch rolls are standardized<details class="details custom-block"><summary>Strafe/perch standardization details</summary><p>When the dragon spawns or rolls a strafe, a standardized random number between 0 and 1 is chosen. The dragon strafes when the probability of having not yet rolled a strafe drops below the random number.</p><p>Perch standardization is similar, however the dragon also perches if the probability of having not yet rolled a perch drops below 0.1.</p></details></li></ul>',30)])])}const u=a(o,[["render",l]]);export{c as __pageData,u as default};
